def fix_spaces(text):
    new_text = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count == 1:
                new_text.append('_')
            elif space_count > 1:
                new_text.append('-')
            new_text.append(char)
            space_count = 0

    if space_count == 1:
        new_text.append('_')
    elif space_count > 1:
        new_text.append('-')

    return ''.join(new_text)
